import { WorkflowEntrypoint, WorkflowEvent, WorkflowStep } from "cloudflare:workers";

interface Env {
  BUCKET: R2Bucket;
  WF: Workflow;
  MODAL_URL: string;
  TTS_API_KEY: string;
  MODAL_PROXY_KEY: string;
  MODAL_PROXY_SECRET: string;
  MODAL_PROXY_URL: string;
}

type Params = { paragraphs: string[]; voice?: string; mode?: "stream" | "step-result"; auth?: "key" | "proxy" };

const now = () => Date.now();

export class TtsWorkflow extends WorkflowEntrypoint<Env, Params> {
  async run(event: WorkflowEvent<Params>, step: WorkflowStep) {
    const { paragraphs, voice, mode = "stream" } = event.payload;
    const proxy = event.payload.auth === "proxy";
    const base = proxy ? this.env.MODAL_PROXY_URL : this.env.MODAL_URL;
    const headers: Record<string, string> = proxy
      ? { "Modal-Key": this.env.MODAL_PROXY_KEY, "Modal-Secret": this.env.MODAL_PROXY_SECRET }
      : { "X-Api-Key": this.env.TTS_API_KEY };

    const submitted = await step.do("submit", async () => {
      const t = now();
      const res = await fetch(`${base}/submit`, {
        method: "POST",
        headers: { ...headers, "content-type": "application/json" },
        body: JSON.stringify({ paragraphs, voice }),
      });
      if (!res.ok) throw new Error(`submit ${res.status}`);
      const body = (await res.json()) as { call_id: string };
      return { callId: body.call_id, ms: now() - t, startedAt: t };
    });

    const polls: { ms: number; status: number }[] = [];
    let attempt = 0;
    for (;;) {
      const r = await step.do(`poll-${attempt}`, async () => {
        const t = now();
        const res = await fetch(`${base}/result/${submitted.callId}?part=meta`, { headers });
        const text = await res.text();
        return { status: res.status, ms: now() - t, bytes: text.length, meta: res.status === 200 ? JSON.parse(text) : null };
      });
      polls.push({ ms: r.ms, status: r.status });
      if (r.status === 200) {
        var meta = r.meta;
        var metaBytes = r.bytes;
        break;
      }
      if (r.status !== 202) throw new Error(`poll ${r.status}`);
      attempt++;
      await step.sleep(`sleep-${attempt}`, "5 seconds");
    }
    const doneAt = now();

    const key = `audio/${event.instanceId}.ogg`;
    const stored = await step.do("store-audio", async () => {
      const t = now();
      const res = await fetch(`${base}/result/${submitted.callId}?part=audio`, { headers });
      if (!res.ok || res.body == null) throw new Error(`audio ${res.status}`);
      const len = res.headers.get("content-length");
      let streamed = false;
      let error: string | null = null;
      if (mode === "stream") {
        try {
          await this.env.BUCKET.put(key, res.body, { httpMetadata: { contentType: "audio/ogg" } });
          streamed = true;
        } catch (e) {
          error = String(e);
        }
      }
      return { ms: now() - t, contentLength: len, streamed, error, headers: Object.fromEntries(res.headers) };
    });

    if (!stored.streamed) {
      // fallback: buffer in the step (fits in 128 MB), write to R2, still return only small data
      await step.do("store-audio-buffered", async () => {
        const res = await fetch(`${base}/result/${submitted.callId}?part=audio`, { headers });
        const buf = await res.arrayBuffer();
        await this.env.BUCKET.put(key, buf, { httpMetadata: { contentType: "audio/ogg" } });
        return { bytes: buf.byteLength };
      });
    }

    if (mode === "step-result") {
      // expected to fail: the 1 MiB step result limit
      await step.do("return-audio-in-result", async () => {
        const res = await fetch(`${base}/result/${submitted.callId}?part=full`, { headers });
        return await res.json();
      });
    }

    const head = await this.env.BUCKET.head(key);
    return {
      key,
      r2Size: head?.size,
      callId: submitted.callId,
      submitMs: submitted.ms,
      synthWallMs: doneAt - submitted.startedAt,
      polls,
      metaBytes,
      duration: meta.duration,
      format: meta.format,
      paragraphs: meta.paragraphs.length,
      stored,
    };
  }
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    if (req.method === "POST" && url.pathname === "/run") {
      const body = (await req.json()) as Params;
      const inst = await env.WF.create({ params: body });
      return Response.json({ id: inst.id });
    }
    const m = url.pathname.match(/^\/status\/(.+)$/);
    if (m) {
      const inst = await env.WF.get(m[1]);
      return Response.json(await inst.status());
    }
    const a = url.pathname.match(/^\/audio\/(.+)$/);
    if (a) {
      const o = await env.BUCKET.get(`audio/${a[1]}.ogg`);
      return o ? new Response(o.body, { headers: { "content-type": "audio/ogg" } }) : new Response("nf", { status: 404 });
    }
    return new Response("ok");
  },
};

