import {
  DurableObject,
  WorkflowEntrypoint,
  type WorkflowEvent,
  type WorkflowStep,
  type WorkflowStepConfig,
  type WorkflowStepContext,
} from "cloudflare:workers";
import { NonRetryableError } from "cloudflare:workflows";

interface Env {
  DB: D1Database;
  BUCKET: R2Bucket;
  ITEM_WF: Workflow<Params>;
  DOMAIN_QUEUE: DurableObjectNamespace<DomainQueue>;
  MODAL_URL: string;
  TTS_API_KEY: string;
  FIRECRAWL_API_KEY: string;
  LEASE_ALARM_MS: string;
}

type LeaseMode = "event" | "poll";

interface Params {
  url: string;
  domain: string;
  paragraphs?: string[];
  voice?: string;
  lease: LeaseMode;
  release: "catch" | "rollback";
  holdSeconds: number;
  fail?: { step: string; attempts: number | "always" };
  delayBeforeWaitSeconds?: number;
  leasePollSeconds?: number;
  leaseWaitTimeout?: string;
  ttsPollSeconds?: number;
}

// ---------------------------------------------------------------- DomainQueue

interface Holder {
  holder: string;
  mode: LeaseMode;
}

interface Lease extends Holder {
  since: number;
}

type Acquire = { granted: true } | { granted: false; position: number };

const TERMINAL = new Set(["complete", "errored", "terminated"]);

export class DomainQueue extends DurableObject<Env> {
  private note(line: string) {
    const log = this.ctx.storage.kv.get<string[]>("log") ?? [];
    log.push(`${new Date().toISOString()} ${line}`);
    this.ctx.storage.kv.put("log", log.slice(-200));
  }

  private lease(): Lease | undefined {
    return this.ctx.storage.kv.get<Lease>("lease");
  }

  private waiting(): Holder[] {
    return this.ctx.storage.kv.get<Holder[]>("waiting") ?? [];
  }

  private grant(next: Holder) {
    this.ctx.storage.kv.put("lease", { ...next, since: Date.now() });
    this.ctx.storage.setAlarm(Date.now() + Number(this.env.LEASE_ALARM_MS));
  }

  // Synchronous KV only: no await inside, so no other call can interleave.
  acquire(holder: string, mode: LeaseMode): Acquire {
    const lease = this.lease();

    if (lease?.holder === holder) {
      return { granted: true };
    }

    const waiting = this.waiting();

    if (lease == null && (waiting.length === 0 || waiting[0].holder === holder)) {
      this.ctx.storage.kv.put(
        "waiting",
        waiting.filter((entry) => entry.holder !== holder),
      );
      this.grant({ holder, mode });
      this.note(`acquire ${holder} (${mode}) granted`);
      return { granted: true };
    }

    let position = waiting.findIndex((entry) => entry.holder === holder);

    if (position === -1) {
      waiting.push({ holder, mode });
      this.ctx.storage.kv.put("waiting", waiting);
      position = waiting.length - 1;
      this.note(`acquire ${holder} (${mode}) queued at ${position}`);
    }

    return { granted: false, position };
  }

  // Leaving the queue entirely: drops a waiting entry as well as a held lease.
  async release(holder: string, reason: string): Promise<{ released: boolean }> {
    return this.ctx.blockConcurrencyWhile(async () => {
      const waiting = this.waiting();

      if (waiting.some((entry) => entry.holder === holder)) {
        this.ctx.storage.kv.put(
          "waiting",
          waiting.filter((entry) => entry.holder !== holder),
        );
        this.note(`release ${holder} from waiting (${reason})`);
      }

      if (this.lease()?.holder !== holder) {
        this.note(`release ${holder} ignored, not the holder (${reason})`);
        return { released: false };
      }

      this.ctx.storage.kv.delete("lease");
      this.note(`release ${holder} (${reason})`);
      await this.advance();
      return { released: true };
    });
  }

  // Hands the lease to the next live waiter. A polling waiter finds it on its
  // next poll; an event waiter is signalled.
  private async advance() {
    const waiting = this.waiting();

    while (waiting.length > 0) {
      const next = waiting.shift() as Holder;
      this.ctx.storage.kv.put("waiting", waiting);

      let status: string;

      try {
        status = (await (await this.env.ITEM_WF.get(next.holder)).status()).status;
      } catch (error) {
        this.note(`advance skip ${next.holder}: status threw ${String(error)}`);
        continue;
      }

      if (TERMINAL.has(status)) {
        this.note(`advance skip ${next.holder}: ${status}`);
        continue;
      }

      this.grant(next);

      if (next.mode === "event") {
        try {
          const instance = await this.env.ITEM_WF.get(next.holder);
          await instance.sendEvent({ type: "lease-granted", payload: { at: Date.now() } });
          this.note(`advance grant ${next.holder} (event sent, was ${status})`);
        } catch (error) {
          this.ctx.storage.kv.delete("lease");
          this.note(`advance skip ${next.holder}: sendEvent threw ${String(error)}`);
          continue;
        }
      } else {
        this.note(`advance grant ${next.holder} (poll, was ${status})`);
      }

      return;
    }

    this.ctx.storage.deleteAlarm();
  }

  async alarm() {
    await this.ctx.blockConcurrencyWhile(async () => {
      const lease = this.lease();

      if (lease == null) {
        return;
      }

      let status: string;

      try {
        status = (await (await this.env.ITEM_WF.get(lease.holder)).status()).status;
      } catch (error) {
        status = `unaddressable: ${String(error)}`;
      }

      if (TERMINAL.has(status) || status.startsWith("unaddressable")) {
        this.ctx.storage.kv.delete("lease");
        this.note(`alarm swept ${lease.holder} (${status})`);
        await this.advance();
        return;
      }

      this.ctx.storage.setAlarm(Date.now() + Number(this.env.LEASE_ALARM_MS));
    });
  }

  dump() {
    return { lease: this.lease() ?? null, waiting: this.waiting(), log: this.ctx.storage.kv.get<string[]>("log") ?? [] };
  }
}

const queueOf = (env: Env, domain: string) => env.DOMAIN_QUEUE.get(env.DOMAIN_QUEUE.idFromName(domain));

// ---------------------------------------------------------------- Workflow

const FETCH: WorkflowStepConfig = { retries: { limit: 3, delay: "5 seconds", backoff: "exponential" }, timeout: "2 minutes" };
const LEASE: WorkflowStepConfig = { retries: { limit: 5, delay: "2 seconds", backoff: "exponential" }, timeout: "30 seconds" };
const RECIPE: WorkflowStepConfig = { retries: { limit: 1, delay: "5 seconds", backoff: "constant" }, timeout: "15 minutes" };
const LOCAL: WorkflowStepConfig = { retries: { limit: 2, delay: "3 seconds", backoff: "constant" }, timeout: "5 minutes" };
const TTS_SUBMIT: WorkflowStepConfig = { retries: { limit: 3, delay: "10 seconds", backoff: "exponential" }, timeout: "1 minute" };
const TTS_POLL: WorkflowStepConfig = { retries: { limit: 5, delay: "5 seconds", backoff: "linear" }, timeout: "30 seconds" };
const STORE: WorkflowStepConfig = { retries: { limit: 3, delay: "5 seconds", backoff: "exponential" }, timeout: "2 minutes" };

const MAX_TTS_POLLS = 2000;

export class ItemWorkflow extends WorkflowEntrypoint<Env, Params> {
  private async log(itemId: string, stepName: string, attempt: number, outcome: string) {
    await this.env.DB.prepare("INSERT INTO step_runs (item_id, step, attempt, outcome, at) VALUES (?, ?, ?, ?, ?)")
      .bind(itemId, stepName, attempt, outcome, Date.now())
      .run();
  }

  private async setStatus(itemId: string, status: string, extra: { error?: string } = {}) {
    await this.env.DB.prepare("UPDATE items SET status = ?, error = COALESCE(?, error), updated_at = ? WHERE id = ?")
      .bind(status, extra.error ?? null, Date.now(), itemId)
      .run();
  }

  async run(event: WorkflowEvent<Params>, step: WorkflowStep) {
    const params = event.payload;
    const itemId = event.instanceId;
    const queue = queueOf(this.env, params.domain);

    // Every attempt is recorded in D1 so a resume can be told apart from a re-run.
    const tracked = <T extends Rpc.Serializable<T>>(
      name: string,
      config: WorkflowStepConfig,
      body: (ctx: WorkflowStepContext) => Promise<T>,
      rollback?: () => Promise<void>,
    ) =>
      step.do(
        name,
        config,
        async (ctx) => {
          await this.log(itemId, name, ctx.attempt, "start");

          const fail = params.fail;

          if (fail != null && fail.step === name && (fail.attempts === "always" || ctx.attempt <= fail.attempts)) {
            await this.log(itemId, name, ctx.attempt, "injected failure");
            throw new Error(`injected failure in ${name}, attempt ${ctx.attempt}`);
          }

          const result = await body(ctx);
          await this.log(itemId, name, ctx.attempt, "ok");
          return result;
        },
        rollback == null
          ? undefined
          : {
              rollback: async () => {
                await this.log(itemId, `${name} (rollback)`, 0, "start");
                await rollback();
              },
              rollbackConfig: { retries: { limit: 3, delay: "5 seconds", backoff: "linear" }, timeout: "1 minute" },
            },
      );

    try {
      const page = await tracked("fetch", FETCH, async () => {
        await this.setStatus(itemId, "fetching");

        if (params.paragraphs != null) {
          return { title: "(provided)", paragraphs: params.paragraphs };
        }

        const res = await fetch("https://api.firecrawl.dev/v2/scrape", {
          method: "POST",
          headers: { "content-type": "application/json", authorization: `Bearer ${this.env.FIRECRAWL_API_KEY}` },
          body: JSON.stringify({ url: params.url, formats: ["markdown"], onlyMainContent: true }),
        });

        if (!res.ok) {
          throw new Error(`firecrawl ${res.status}`);
        }

        const body = (await res.json()) as { data?: { markdown?: string; metadata?: { title?: string } } };
        const paragraphs = (body.data?.markdown ?? "")
          .split(/\n\s*\n/)
          .map((block) => block.replace(/[#*_`>[\]]/g, "").replace(/\(http[^)]*\)/g, "").trim())
          .filter((block) => block.split(/\s+/).length >= 8);

        return { title: body.data?.metadata?.title ?? "", paragraphs };
      });

      await this.lease(itemId, params, step, tracked, queue);

      await tracked("recipe", RECIPE, async () => {
        await this.setStatus(itemId, "extracting");
        await scheduler.wait(params.holdSeconds * 1000);
        return { units: page.paragraphs.length };
      });

      await tracked("lease: release", LEASE, () => queue.release(itemId, "done with recipe"));

      await tracked("images", LOCAL, async () => {
        await this.setStatus(itemId, "images");
        return { images: 0 };
      });

      await tracked("describe", LOCAL, async () => {
        await this.setStatus(itemId, "describing");
        return { described: 0 };
      });

      const submitted = await tracked("tts: submit", TTS_SUBMIT, async () => {
        await this.setStatus(itemId, "synthesizing");

        const res = await fetch(`${this.env.MODAL_URL}/submit`, {
          method: "POST",
          headers: { "content-type": "application/json", "X-Api-Key": this.env.TTS_API_KEY },
          body: JSON.stringify({ paragraphs: page.paragraphs, voice: params.voice }),
        });

        if (!res.ok) {
          throw new Error(`tts submit ${res.status}`);
        }

        return { callId: ((await res.json()) as { call_id: string }).call_id, at: Date.now() };
      });

      let meta: { duration: number; paragraphs: unknown[] } | null = null;

      for (let n = 1; meta == null; n += 1) {
        if (n > MAX_TTS_POLLS) {
          throw new NonRetryableError(`tts still running after ${MAX_TTS_POLLS} polls`);
        }

        await step.sleep(`tts: sleep ${n}`, (params.ttsPollSeconds ?? 5) * 1000);

        const polled = await tracked(`tts: poll ${n}`, TTS_POLL, async () => {
          const res = await fetch(`${this.env.MODAL_URL}/result/${submitted.callId}?part=meta`, {
            headers: { "X-Api-Key": this.env.TTS_API_KEY },
          });

          if (res.status === 202) {
            return { done: false as const };
          }

          if (!res.ok) {
            throw new Error(`tts poll ${res.status}: ${(await res.text()).slice(0, 200)}`);
          }

          const body = (await res.json()) as { duration: number; paragraphs: unknown[] };
          return { done: true as const, duration: body.duration, paragraphs: body.paragraphs };
        });

        if (polled.done) {
          meta = { duration: polled.duration, paragraphs: polled.paragraphs };
        }
      }

      const finished = meta;

      const stored = await tracked("store", STORE, async () => {
        const res = await fetch(`${this.env.MODAL_URL}/result/${submitted.callId}?part=audio`, {
          headers: { "X-Api-Key": this.env.TTS_API_KEY },
        });

        if (!res.ok || res.body == null) {
          throw new Error(`tts audio ${res.status}`);
        }

        const key = `audio/${itemId}.ogg`;
        await this.env.BUCKET.put(key, res.body, { httpMetadata: { contentType: "audio/ogg" } });
        await this.env.DB.prepare(
          "UPDATE items SET status = 'ready', audio_key = ?, duration = ?, units_json = ?, updated_at = ? WHERE id = ?",
        )
          .bind(key, finished.duration, JSON.stringify(finished.paragraphs), Date.now(), itemId)
          .run();

        return { key, synthMs: Date.now() - submitted.at };
      });

      return { ...stored, duration: finished.duration };
    } catch (error) {
      await step.do("mark failed", async () => {
        await this.setStatus(itemId, "failed", { error: String(error) });
        return null;
      });
      throw error;
    }
  }

  private async lease(
    itemId: string,
    params: Params,
    step: WorkflowStep,
    tracked: <T extends Rpc.Serializable<T>>(
      name: string,
      config: WorkflowStepConfig,
      body: (ctx: WorkflowStepContext) => Promise<T>,
      rollback?: () => Promise<void>,
    ) => Promise<T>,
    queue: DurableObjectStub<DomainQueue>,
  ) {
    const releaseOnRollback =
      params.release === "rollback" ? async () => void (await queue.release(itemId, "rollback")) : undefined;

    const request = await tracked(
      "lease: request",
      LEASE,
      async () => {
        await this.setStatus(itemId, "waiting_lease");
        return queue.acquire(itemId, params.lease);
      },
      releaseOnRollback,
    );

    if (request.granted) {
      return;
    }

    if (params.lease === "poll") {
      for (let n = 1; ; n += 1) {
        await step.sleep(`lease: sleep ${n}`, (params.leasePollSeconds ?? 5) * 1000);
        const polled = await tracked(`lease: poll ${n}`, LEASE, () => queue.acquire(itemId, "poll"));

        if (polled.granted) {
          return;
        }
      }
    }

    if (params.delayBeforeWaitSeconds != null) {
      await step.sleep("lease: pre-wait delay", params.delayBeforeWaitSeconds * 1000);
    }

    // A lost or early event is recovered by re-asking the queue after a timeout.
    for (let n = 1; ; n += 1) {
      try {
        await step.waitForEvent(`lease: wait ${n}`, { type: "lease-granted", timeout: params.leaseWaitTimeout ?? "10 minutes" });
        return;
      } catch (error) {
        const recheck = await tracked(`lease: recheck ${n}`, LEASE, () => queue.acquire(itemId, "event"));

        if (recheck.granted) {
          return;
        }
      }
    }
  }
}

// ---------------------------------------------------------------- Worker

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body, null, 2), { status, headers: { "content-type": "application/json" } });

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    const parts = url.pathname.split("/").filter(Boolean);

    if (req.method === "POST" && url.pathname === "/items") {
      const body = (await req.json()) as Partial<Params> & { url: string; id?: string };
      const id = body.id ?? `item-${crypto.randomUUID().slice(0, 8)}`;
      const params: Params = {
        lease: "event",
        release: "catch",
        holdSeconds: 20,
        ...body,
        domain: body.domain ?? new URL(body.url).hostname,
      };

      await env.DB.prepare("INSERT INTO items (id, url, domain, status, updated_at) VALUES (?, ?, ?, 'queued', ?)")
        .bind(id, params.url, params.domain, Date.now())
        .run();
      await env.ITEM_WF.create({ id, params });
      return json({ id, params: { ...params, paragraphs: params.paragraphs?.length } });
    }

    if (parts[0] === "items" && parts[1] != null) {
      const id = parts[1];
      const instance = await env.ITEM_WF.get(id);

      if (req.method === "POST" && parts[2] === "terminate") {
        await instance.terminate({ rollback: url.searchParams.get("rollback") === "1" });
        return json({ terminated: id });
      }

      if (req.method === "POST" && parts[2] === "restart") {
        const from = url.searchParams.get("from");
        await instance.restart(from == null ? undefined : { from: { name: from, count: Number(url.searchParams.get("count") ?? 1) } });
        return json({ restarted: id, from });
      }

      if (req.method === "POST" && parts[2] === "event") {
        await instance.sendEvent({ type: "lease-granted", payload: { manual: true } });
        return json({ sent: id });
      }

      const item = await env.DB.prepare("SELECT id, url, domain, status, error, audio_key, duration, updated_at FROM items WHERE id = ?").bind(id).first();
      const runs = await env.DB.prepare("SELECT step, attempt, outcome, at FROM step_runs WHERE item_id = ? ORDER BY seq").bind(id).all();
      return json({ item, status: await instance.status(), runs: runs.results });
    }

    if (parts[0] === "queue" && parts[1] != null) {
      return json(await queueOf(env, parts[1]).dump());
    }

    if (req.method === "POST" && parts[0] === "release" && parts[1] != null && parts[2] != null) {
      return json(await queueOf(env, parts[1]).release(parts[2], "manual"));
    }

    return new Response("nagara-spike-item-wf");
  },
};

